#pragma once
// itch-parser.hpp
// Nasdaq TotalView-ITCH 5.0 over MoldUDP64, received on a UDP socket (unicast or multicast).
// Executions and trades become Ticks; every other message type is skipped.
//
// Limits:
//  - no order book: Order Executed ('E') carries no price, so its Tick has price == no_price
//  - no retransmission requests: lost messages are counted in stats().lost_messages
//  - Broken Trade ('B') is ignored, the volume is not backed out

#include "../tick.hpp"

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#include <array>
#include <atomic>
#include <cerrno>
#include <cstddef>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <system_error>
#include <utility>

// Handler needs: void on_tick(const Tick&).
// It is stored by value; pass a reference type (ItchParser<MyHandler&>) to share one.
template <typename Handler>
requires requires(Handler& h, const Tick& t) { h.on_tick(t); }
class ItchParser{

    public:

    static constexpr std::int64_t no_price = 0;

    struct Config{
        std::string group{};                  // multicast group to join, empty for unicast
        std::string interface_ip{"0.0.0.0"};  // local interface used for the join
        std::uint16_t port = 0;
        std::uint16_t stock_locate = 0;       // 0: every instrument
        int rcvbuf_bytes = 0;                 // 0: kernel default
        bool busy_spin = true;                // false: block in recv(), wake every 100ms to check stop()
    };

    struct Stats{
        std::uint64_t packets{0};
        std::uint64_t messages{0};        // ITCH messages decoded, all types
        std::uint64_t ticks{0};
        std::uint64_t lost_messages{0};   // from MoldUDP64 sequence gaps
        std::uint64_t malformed{0};       // truncated packets or messages
        bool end_of_session{false};
    };

    // Opens and binds the socket. Throws std::system_error / std::invalid_argument.
    explicit ItchParser(Handler handler, Config cfg)
        : _handler(std::forward<Handler>(handler)), _cfg(std::move(cfg)) {
        open_socket();
    }

    ~ItchParser(){
        if ( _fd >= 0 )
            ::close(_fd);
    }

    ItchParser(const ItchParser&) = delete;
    ItchParser& operator=(const ItchParser&) = delete;

    // Blocks on the calling thread until stop() is called or the session ends.
    void start(){

        const int flags = _cfg.busy_spin ? MSG_DONTWAIT : 0;

        while ( !_stop.load(std::memory_order_relaxed) ){

            const ssize_t received = ::recv(_fd, _rx.data(), _rx.size(), flags);

            if ( received < 0 ){
                if ( errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR )
                    continue;
                throw std::system_error(errno, std::generic_category(), "recv");
            }

            if ( !parse_packet(_rx.data(), static_cast<std::size_t>(received)) )
                return; // end of session
        }
    }

    // Safe from another thread or from a signal handler.
    void stop(){
        _stop.store(true, std::memory_order_relaxed);
    }

    // Decode one MoldUDP64 datagram. Public so captures can be replayed without a socket.
    // Returns false once the end-of-session packet has been seen.
    bool parse_packet(const std::uint8_t* data, std::size_t len){

        ++_stats.packets;

        if ( len < mold_header_size ){
            ++_stats.malformed;
            return true;
        }

        // session (10 bytes) is not checked
        const std::uint64_t sequence = load_be<8>(data + 10);
        const std::uint64_t count = load_be<2>(data + 18);

        if ( count == mold_end_of_session ){
            _stats.end_of_session = true;
            return false;
        }

        // A heartbeat (count == 0) carries the next expected sequence, so it reveals gaps too
        if ( _next_sequence != 0 && sequence > _next_sequence )
            _stats.lost_messages += sequence - _next_sequence;

        std::size_t offset = mold_header_size;

        for(std::uint64_t i = 0 ; i < count ; i++){

            if ( offset + 2 > len ){
                ++_stats.malformed;
                break;
            }

            const std::size_t message_len = load_be<2>(data + offset);
            offset += 2;

            if ( offset + message_len > len ){
                ++_stats.malformed;
                break;
            }

            // Already seen (other line of an A/B pair, or a replay): skip
            if ( sequence + i >= _next_sequence )
                on_message(data + offset, message_len);

            offset += message_len;
        }

        if ( sequence + count > _next_sequence )
            _next_sequence = sequence + count;

        return true;
    }

    // Parser thread only (or after start() has returned).
    const Stats& stats() const{
        return _stats;
    }

    Handler& handler(){
        return _handler;
    }

    private:

    static constexpr std::size_t mold_header_size = 20;
    static constexpr std::uint64_t mold_end_of_session = 0xFFFF;

    // Every ITCH message starts with: type(1) stock locate(2) tracking number(2) timestamp(6)
    static constexpr std::size_t itch_header_size = 11;

    template <std::size_t nbytes>
    static std::uint64_t load_be(const std::uint8_t* p){
        std::uint64_t value = 0;
        for(std::size_t i = 0 ; i < nbytes ; i++)
            value = (value << 8) | p[i];
        return value;
    }

    void on_message(const std::uint8_t* msg, std::size_t len){

        if ( len < itch_header_size ){
            ++_stats.malformed;
            return;
        }

        ++_stats.messages;

        if ( _cfg.stock_locate != 0 && load_be<2>(msg + 1) != _cfg.stock_locate )
            return;

        std::uint64_t price = 0;
        std::uint64_t qty = 0;

        switch ( msg[0] ){

            case 'E': // Order Executed: shares at 19, no price
                if ( len < 31 ) { ++_stats.malformed; return; }
                price = static_cast<std::uint64_t>(no_price);
                qty = load_be<4>(msg + 19);
                break;

            case 'C': // Order Executed With Price: shares at 19, printable at 31, price at 32
                if ( len < 36 ) { ++_stats.malformed; return; }
                if ( msg[31] == 'N' )
                    return; // non-printable: already counted in a cross or trade message
                qty = load_be<4>(msg + 19);
                price = load_be<4>(msg + 32);
                break;

            case 'P': // Trade (non-cross): shares at 20, price at 32
                if ( len < 44 ) { ++_stats.malformed; return; }
                qty = load_be<4>(msg + 20);
                price = load_be<4>(msg + 32);
                break;

            case 'Q': // Cross Trade: shares at 11 (8 bytes), price at 27
                if ( len < 40 ) { ++_stats.malformed; return; }
                qty = load_be<8>(msg + 11);
                price = load_be<4>(msg + 27);
                break;

            default:
                return;
        }

        // timestamp: nanoseconds since midnight. price: 4 implied decimals.
        _handler.on_tick(Tick{static_cast<std::int64_t>(load_be<6>(msg + 5)),
                              static_cast<std::int64_t>(price),
                              static_cast<std::int64_t>(qty)});
        ++_stats.ticks;
    }

    void open_socket(){

        const bool multicast = !_cfg.group.empty();

        ip_mreq membership{};
        if ( multicast && ::inet_pton(AF_INET, _cfg.group.c_str(), &membership.imr_multiaddr) != 1 )
            throw std::invalid_argument("ItchParser: bad multicast group " + _cfg.group);
        if ( ::inet_pton(AF_INET, _cfg.interface_ip.c_str(), &membership.imr_interface) != 1 )
            throw std::invalid_argument("ItchParser: bad interface address " + _cfg.interface_ip);

        _fd = ::socket(AF_INET, SOCK_DGRAM, 0);
        if ( _fd < 0 )
            throw std::system_error(errno, std::generic_category(), "socket");

        const int on = 1;
        if ( ::setsockopt(_fd, SOL_SOCKET, SO_REUSEADDR, &on, sizeof(on)) != 0 )
            fail("setsockopt(SO_REUSEADDR)");

        if ( _cfg.rcvbuf_bytes > 0
             && ::setsockopt(_fd, SOL_SOCKET, SO_RCVBUF, &_cfg.rcvbuf_bytes, sizeof(_cfg.rcvbuf_bytes)) != 0 )
            fail("setsockopt(SO_RCVBUF)");

        if ( !_cfg.busy_spin ){
            const timeval timeout{0, 100'000};
            if ( ::setsockopt(_fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) != 0 )
                fail("setsockopt(SO_RCVTIMEO)");
        }

        // Binding to the group keeps out datagrams for other groups on the same port
        sockaddr_in address{};
        address.sin_family = AF_INET;
        address.sin_port = htons(_cfg.port);
        address.sin_addr = multicast ? membership.imr_multiaddr : membership.imr_interface;

        if ( ::bind(_fd, reinterpret_cast<const sockaddr*>(&address), sizeof(address)) != 0 )
            fail("bind");

        if ( multicast
             && ::setsockopt(_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &membership, sizeof(membership)) != 0 )
            fail("setsockopt(IP_ADD_MEMBERSHIP)");
    }

    // The destructor does not run when the constructor throws, so close here
    [[noreturn]] void fail(const char* what){
        const int error = errno;
        ::close(_fd);
        _fd = -1;
        throw std::system_error(error, std::generic_category(), what);
    }

    Handler _handler;
    Config _cfg;

    int _fd{-1};

    // Next MoldUDP64 sequence number expected, 0 until the first packet
    std::uint64_t _next_sequence{0};

    Stats _stats;

    std::atomic<bool> _stop{false};

    // Largest possible UDP datagram
    std::array<std::uint8_t, 65536> _rx;

};
